/**
 * Igbo locale (ig) - implemented in 4.3.0 from docs/locales/ig-SPEC.md
 * (sources quoted there). Decimal system, multiplier-after scales, every
 * component boundary joined by "na". The 100-vs-200 asymmetry ("otu narị"
 * but "narị abụọ") is attested and intentionally preserved.
 *
 * Words for 0..99 are GENERATED by the rules below. Ordinals are periphrastic
 * ("nke mbụ", "nke abụọ" - SPEC §5); decimal inputs reject loudly (no
 * decimalOrdinal hook yet); currency mode works.
 */

import { illionName } from "../illions.js";
import type { LocaleDefinition } from "./types.js";

const UNITS = [
  "otu",
  "abụọ",
  "atọ",
  "anọ",
  "ise",
  "isii",
  "asaa",
  "asatọ",
  "itoolu",
] as const;

/** Builds the 0..99 word table from the verified rules (SPEC §2). */
function buildSmallNumbers(): string[] {
  const table: string[] = [];

  table[0] = "efu";
  UNITS.forEach((word, index) => {
    table[index + 1] = word;
  });

  table[10] = "iri";
  UNITS.forEach((word, index) => {
    table[11 + index] = `iri na ${word}`; // iri na otu ... iri na itoolu
  });

  // Tens 20-90: iri + multiplier unit (iri abụọ = 20 ... iri itoolu = 90)
  UNITS.slice(1).forEach((word, index) => {
    const base = 20 + index * 10;
    table[base] = `iri ${word}`;
    table[base + 1] = `iri ${word} na otu`; // X1 is always "na otu"
    UNITS.slice(1).forEach((unitWord, unitIndex) => {
      table[base + 2 + unitIndex] = `iri ${word} na ${unitWord}`;
    });
  });

  return table;
}

/** Attested scale loans; beyond 10^9 the English name is used (SPEC §4). */
function igScaleName(groupIndex: number): string {
  switch (groupIndex) {
    case 2:
      return "nde"; // 10^6
    case 3:
      return "ijiri"; // 10^9
    default:
      return illionName(groupIndex - 1).toLowerCase(); // documented code-switch
  }
}

/** Scale-first for the loans, with the explicit "otu" for a multiplier of 1. */
function igScaleWord(groupIndex: number, groupValue: number, groupWords: string): string {
  return groupValue === 1
    ? `otu ${igScaleName(groupIndex)}`
    : `${igScaleName(groupIndex)} ${groupWords}`;
}

/**
 * Periphrastic ordinals (SPEC §5, sources: ResearchGate Igbo/Igala comparison +
 * Harvard Igbo materials): "nke" + cardinal, with the special "nke mbụ" for
 * first ("mbụ" = first/foremost, not derived from otu).
 */
function igOrdinalize(cardinal: string): string {
  return cardinal === "otu" ? "nke mbụ" : `nke ${cardinal}`;
}

export const igLocale: LocaleDefinition = {
  code: "ig",
  zeroWord: "efu",
  smallNumbers: buildSmallNumbers(),
  hundredWord: "narị",
  thousandWord: "puku",
  negativePrefix: "(negative) ", // OPEN ITEM (SPEC §5): unlocalized pending a source
  dotSeparator: "(dot) ", // unreachable - decimals are rejected (SPEC §5)
  andStyle: "british",
  andWord: "na", // iri atọ na anọ, otu puku na otu narị
  supportsBothStyles: false,
  groupSeparator: " na ",
  scaleWordFor: igScaleWord,
  ordinalize: igOrdinalize,
  // 100 = "otu narị" (explicit otu) but 200+ = "narị abụọ" - attested asymmetry.
  hundredPhraseFor: (hundreds) =>
    hundreds === 1 ? "otu narị" : `narị ${UNITS[hundreds - 1]}`,
  thousandPhraseFor: (groupValue, groupWords) =>
    groupValue === 1 ? "otu puku" : `puku ${groupWords}`,
};
